 checks=[("Program v4 IOT declaration model","class IotDeclarationConfig" in models and "iot: IotDeclarationConfig" in models and "version: int = 4" in models),("IOT Declaration Workspace installed",(fe/"src/components/ComputerVision/IotDeclarationWorkspace.tsx").exists() and "IOT DECLARATION ENGINE" in (fe/"src/components/ComputerVision/IotDeclarationWorkspace.tsx").read_text(encoding="utf-8")),("Old IOT panel replaced in active page","IotDeclarationWorkspace" in page and "module!='iot'".replace("!=", "!==") in page),("Dynamic declared device endpoints","program.iot.devices" in reg and "device.{device_alias}" in reg),("Declared ROI/Logic objects exist before run","vision.roi.{roi_alias}" in reg and "populated after a run" in reg),("Automation runtime resolves declared points","read_declared_point" in mgr and "write_declared_point" in mgr and "pulse_declared_point" in mgr),("Draft endpoint preview API installed","automation/endpoints/preview" in api),("IDE refreshes endpoints from draft program","automationEndpointsPreview(program)" in ide),("Colored safe DSL editor installed",(fe/"src/components/ComputerVision/AutomationCodeEditor.tsx").exists() and "tokenColor" in (fe/"src/components/ComputerVision/AutomationCodeEditor.tsx").read_text(encoding="utf-8")),("Dot-triggered IntelliSense","e.key==='.'" in (fe/"src/components/ComputerVision/AutomationCodeEditor.tsx").read_text(encoding="utf-8")),("Hierarchical Object Explorer installed",(fe/"src/components/ComputerVision/EndpointObjectTree.tsx").exists() and "OBJECT / ENDPOINT EXPLORER" in ide),("ROI API alias exposed","API alias" in (fe/"src/components/ComputerVision/MasterSamplePanel.tsx").read_text(encoding="utf-8")),("v0.12 regression test installed",(be/"tests/vision_app/test_vision_app_v1200.py").exists()),("v0.12 handoff MD installed",(fe/"docs/llm_context/updates/v1200_iot_declaration_dynamic_ide.md").exists()),("Context generator v0.12","IOT Declaration Engine" in (fe/"tools/generate_llm_context_map.py").read_text(encoding="utf-8") and "object-driven" in (fe/"tools/generate_llm_context_map.py").read_text(encoding="utf-8"))]
 for label,ok in checks: print(f"[{'OK' if ok else 'FAIL'}] {label}");fail+=0 if ok else 1
