def main():
 ap=argparse.ArgumentParser();ap.add_argument("command",choices=["scan","apply","verify"]);ap.add_argument("--frontend");ap.add_argument("--backend");ap.add_argument("--skip-build",action="store_true");a=ap.parse_args()
